def merge_intervals(iv: list) -> list:
    """Merge overlapping or touching [start, end] intervals; return sorted by start."""
    if not iv:
        return []
    # sort by start
    iv_sorted = sorted(iv, key=lambda x: x[0])
    merged = [iv_sorted[0]]
    for cur in iv_sorted[1:]:
        last = merged[-1]
        # if current starts before or at last.end+1 => merge (touching merges)
        if cur[0] <= last[1] + 1:
            merged[-1] = [last[0], max(last[1], cur[1])]
        else:
            merged.append(cur)
    return merged

