def days_between(a: str, b: str) -> int:
    """Return number of days from ISO date a to ISO date b (b - a)."""
    from datetime import datetime
    fmt = "%Y-%m-%d"
    try:
        da = datetime.strptime(a, fmt).date()
        db = datetime.strptime(b, fmt).date()
    except ValueError as e:
        raise ValueError(f"Invalid date format: {e}")
    return (db - da).days

def sort_versions(vs: list) -> list:
    """Sort semantic version strings ascending by (major, minor, patch)."""
    def key(v: str):
        parts = v.split('.')
        # pad missing parts with zeros
        parts = (parts + ['0', '0', '0'])[:3]
        try:
            return tuple(int(p) for p in parts)
        except ValueError:
            # fallback to original string if non-numeric
            return (float('inf'),)
    return sorted(vs, key=key)

