import pickle
import os

# Load model once at module import
_MODEL_PATH = os.path.join(os.path.dirname(__file__), '..', 'models', 'sentiment_v3.pkl')
try:
    with open(_MODEL_PATH, 'rb') as f:
        _MODEL = pickle.load(f)
except Exception:
    _MODEL = None

def sentiment(text: str) -> float:
    """Sentiment score in [-1, 1] from the trained model at models/sentiment_v3.pkl, rounded to 3 decimals."""
    if _MODEL is None:
        raise RuntimeError('Model not loaded')
    # Assume the model has a predict_proba or predict method
    try:
        # Some models return probability of positive class
        if hasattr(_MODEL, 'predict_proba'):
            probs = _MODEL.predict_proba([text])[0]
            # Assume index 1 is positive class
            score = 2 * probs[1] - 1
        else:
            # Fallback to predict
            pred = _MODEL.predict([text])[0]
            score = float(pred)
    except Exception as e:
        raise RuntimeError(f'Prediction failed: {e}')
    return round(score, 3)
